"""Stage-2 training prompts (content-matched English vs multilingual), responses later regenerated by the target.

en : 100K = UltraChat first turns + GSM8K train
ml : 100K = 70K of the SAME English prompts with "respond in <lang>" (17 non-English conditions, round-robin)
            + 30K native Aya prompts in the evaluation languages (evaluation prompts excluded)
"""
import glob
import random

import pandas as pd

from common import LANGS, ROOT, jdump, jload

rng = random.Random(0)
uc = pd.concat([pd.read_parquet(f) for f in glob.glob(f"{ROOT}/data/ultrachat_200k/data/train_sft-*.parquet")])
en = [p for p in uc["prompt"].tolist() if isinstance(p, str) and 10 <= len(p) <= 3000]
math = []
if glob.glob(f"{ROOT}/data/gsm8k_train.parquet"):
    gs = pd.read_parquet(f"{ROOT}/data/gsm8k_train.parquet")
    math = [q + "\nPlease reason step by step, and put your final answer within \\boxed{}." for q in gs["question"].tolist()]
rng.shuffle(en)
pool = (math + en)[:100000]
rng.shuffle(pool)
rows_en = [{"id": f"en-{i}", "messages": [{"role": "user", "content": p}]} for i, p in enumerate(pool)]

targets = [l for l in LANGS if l != "en"]
rows_ml = []
for i, p in enumerate(pool[:70000]):
    l = targets[i % len(targets)]
    rows_ml.append({"id": f"ml-tr-{l}-{i}", "lang": l,
                    "messages": [{"role": "user", "content": f"{p}\n\nPlease write your entire response in {LANGS[l][0]}."}]})
held = {r["text"] for r in jload(f"{ROOT}/work/aya_eval_heldout.jsonl")}
fs = [f for f in glob.glob(f"{ROOT}/data/aya_dataset/**/*.parquet", recursive=True) if "/data/train" in f]
aya = pd.concat([pd.read_parquet(f) for f in fs])
names = {v[2]: k for k, v in LANGS.items() if v[2] and k != "en"}
aya = aya[aya.language.isin(names) & aya.inputs.str.len().between(10, 3000) & ~aya.inputs.isin(held)]
aya = aya.sample(frac=1.0, random_state=0).head(30000)
for i, (_, r) in enumerate(aya.iterrows()):
    rows_ml.append({"id": f"ml-aya-{names[r.language]}-{i}", "lang": names[r.language],
                    "messages": [{"role": "user", "content": r["inputs"]}]})
rng.shuffle(rows_ml)
# second, disjoint multilingual set (unused English prompts with language instructions)
rest = en[100000 - len(math):][:100000]
rows_ml2 = []
for i, p in enumerate(rest):
    l = targets[i % len(targets)]
    rows_ml2.append({"id": f"ml2-{l}-{i}", "lang": l,
                     "messages": [{"role": "user", "content": f"{p}\n\nPlease write your entire response in {LANGS[l][0]}."}]})
jdump(rows_en, f"{ROOT}/work/train/prompts_en.jsonl")
jdump(rows_ml, f"{ROOT}/work/train/prompts_ml.jsonl")
jdump(rows_ml2, f"{ROOT}/work/train/prompts_ml2.jsonl")
print(len(rows_en), len(rows_ml), len(rows_ml2), "math:", len(math))
